   <script>
     const dialog = document.getElementById('delete-dialog');
     const trigger = document.querySelector('.trigger');
     const status = document.getElementById('status');
     const closeIcon = dialog.querySelector('.close-icon');
     const cancelButton = dialog.querySelector('[data-action="cancel"]');
     const deleteButton = dialog.querySelector('[data-action="delete"]');

     const openDialog = () => {
       if (!dialog.open) dialog.showModal();
       deleteButton.focus();
       status.textContent = '';
     };

     const closeDialog = (message = '') => {
       if (dialog.open) dialog.close();
       status.textContent = message;
       trigger.focus();
     };

     trigger.addEventListener('click', openDialog);
     closeIcon.addEventListener('click', () => closeDialog());
     cancelButton.addEventListener('click', () => closeDialog('Deletion cancelled.'));

     deleteButton.addEventListener('click', () => {
       closeDialog('Image deleted from your library.');
     });

     dialog.addEventListener('click', (event) => {
       const rect = dialog.getBoundingClientRect();
       const inDialog =
         event.clientX >= rect.left &&
         event.clientX <= rect.right &&
         event.clientY >= rect.top &&
         event.clientY <= rect.bottom;

       if (!inDialog) closeDialog();
     });

     dialog.addEventListener('cancel', () => {
       closeDialog();
     });
   </script>
